    int n;
    cin >> n;

    int chest = 0, biceps = 0, back = 0;

    for (int i = 0; i < n; ++i) {
        int exercise;
        cin >> exercise;

        if (i % 3 == 0)
            chest += exercise;
        else if (i % 3 == 1)
            biceps += exercise;
        else
            back += exercise;
    }

    if (chest >= biceps && chest >= back)
        cout << "chest\n";
    else if (biceps >= chest && biceps >= back)
        cout << "biceps\n";
    else
        cout << "back\n";

    return 0;
}

